import{t as e}from"./utils-COoNfFoj.js";var t={slug:`beatrice-vladut`,influencerName:`Beatrice Vladut`,influencerHandle:`@beatricevladut`,influencerAvatarUrl:`${e}/beatrice-vladut-avatar.png`,heroDescription:`One of my 2026 goals is to speak at 8-10 B2B conferences and I was tired of tracking opportunities across scattered Notion docs, old email threads, and Google searches.`,assetTitle:`Mainstage`,screenshotUrl:`${e}/beatrice-vladut.png`,remixUrl:`https://www.perplexity.ai/computer/a/mainstage-2rh3S2v.SVmXA8RtxzR_yA`,promptTitle:`Try Beatrice's prompt`,promptText:`Build me a Bloomberg-terminal-style web app called Mainstage, a speaking opportunity command center for B2B founders and creators who want to land conference speaking slots in 2026, with the tagline “Find the stage. Land the stage.” and subtitle “Conference Intelligence for B2B Speakers.” It’s for Beatrice Vladut, a B2B LinkedIn creator with 65k followers and founder of Founder Growth, whose 2026 goal is to speak at 5–6 mid-tier B2B and creator economy conferences on founder-led brand building, B2B LinkedIn strategy, and creator-brand partnerships, after getting tired of scattered Notion docs and Google searches and wanting one terminal for research and execution. The design should feel like Bloomberg Terminal meets Linear: deep black background, crimson and hot-pink accents, white and gray text, green/amber/red status colors, dark card surfaces, Inter-style body type with tabular mono numerics, dense but breathable spacing, sharp edges, and subtle pink hover glow. The app includes a sticky header with an M mark, Mainstage wordmark, scrolling CFP countdown ticker, date/time, weather for the next conference city, and profile chip; a hero headline “Find the stage. Land the stage.” with a subtitle showing progress toward tracking 15 conferences and booking 5–6 mainstages, plus a next-deadline countdown widget; three KPI cards for pipeline, open windows, and booked stages; a live intelligence strip with deadlines this week, reachable audience, match score leaders, and geographic spread; a full-width interactive world map with solid continent shapes, glowing pink conference markers, borders, zoom controls, panning, clustering, timezone labels, legends, a furthest-stage panel, scanning-line animation, and filters for region, topic, and CFP status; and a Bloomberg-style conference table with status, conference name, dates, city and flag, audience size, topic tags, live CFP countdown, past speaker avatars, match score, and a pitch button, sorted by nearest CFP deadline with filters and a table/calendar toggle. Populate it with real 2026 conferences including Hypergrowth Boston, SaaStr AI Annual San Mateo, INBOUND, Web Summit Lisbon, MAICON Cleveland, Pavilion GTM2026 NYC, and SaaStock Europe Dublin. Concise edits like this typically remove redundancy, cut filler phrases, and tighten long sentences while preserving the main ideas.`};export{t as default};
